python3 -I -B -c 'from pathlib import Path; import os,sys,json,hashlib,tempfile,subprocess; root=Path.cwd(); logs=[]
def record(s):
 print(s); logs.append(s)
def run(label,argv):
 r=subprocess.run(argv,capture_output=True,text=True); record(label+" exit="+str(r.returncode)+"\n"+r.stdout+r.stderr); return r
run("Verification",[sys.executable,"-I","-B","benchmark/scripts/change_cases.py","--check"])
envroot=Path(os.environ["LABVIEW_ENVIRONMENT"]); pins={}
for name in ["typedef-impact","diagram-difference"]:
 spec=json.loads((root/"benchmark/change-cases"/(name+".spec.json")).read_text())
 for entry in [spec["source"]]+spec.get("consumer_candidates",[]): pins[entry["path"]]=entry["sha256"]
for relative,expected in pins.items():
 p=envroot/relative; digest=hashlib.sha256(p.read_bytes()).hexdigest(); record("Prepared source "+relative+" sha256="+digest+" match="+str(digest==expected))
run("Prepared history",["git","-C",str(envroot/"actor-framework"),"rev-list","--count","HEAD"])
source=(root/"benchmark/scripts/change_cases.py").read_text(); probes=[("disable source pin", "    require((source.get(\"path\"), source.get(\"sha256\"), source.get(\"size_bytes\")) == (PREFIX + filename, digest, size), \"source pin\")", "    pass # source pin check disabled"),("disable owner grant flags", "    require(all(auth.get(k) is True for k in [\"explicit_owner_grant_required_for_edits\", \"explicit_owner_grant_required_for_builds\", \"derived_copies_only\"]) and auth.get(\"grant_obtained\") is False, \"owner grant flags\")", "    pass # owner grant check disabled"),("disable expected reason comparison", "            assert str(exc) == reason, (reason, str(exc))", "            pass # expected reason comparison disabled")]
with tempfile.TemporaryDirectory(prefix="review-408-") as directory:
 temp=Path(directory); (temp/"benchmark/scripts").mkdir(parents=True); (temp/"benchmark/change-cases").mkdir()
 for name in ["typedef-impact","diagram-difference"]:
  relative=Path("benchmark/change-cases")/(name+".spec.json"); (temp/relative).write_bytes((root/relative).read_bytes())
 target=temp/"benchmark/scripts/change_cases.py"; target.write_text(source); run("Temporary positive control",[sys.executable,"-I","-B",str(target),"--check"])
 for label,old,new in probes:
  assert source.count(old)==1, label; target.write_text(source.replace(old,new)); result=run("Revert probe: "+label,[sys.executable,"-I","-B",str(target),"--check"]); record("Required nonzero observed="+str(result.returncode!=0))
artifact=root/".session/artifacts/review-evidence.txt"; artifact.parent.mkdir(parents=True,exist_ok=True); artifact.write_text("\n\n".join(logs)+"\n")'

